// === Tab: Distance Function ===
// Found this function on Stack Overflow:
// https://stackoverflow.com/questions/849211/shortest-distance-between-a-point-and-a-line-segment

function dtoS(lx1, ly1, lx2, ly2, px, py) {
    const lx = lx2 - lx1; // Line segment vector x
    const ly = ly2 - ly1; // Line segment vector y
    const lineLengthSq = lx * lx + ly * ly; // Squared length of the line segment

    // If the line segment has zero length, calculate distance to the single point
    if (lineLengthSq === 0) {
        const dx = px - lx1;
        const dy = py - ly1;
        return Math.sqrt(dx * dx + dy * dy);
    }

    // Calculate 't' (projection parameter). 
    // 't' indicates where the projection of the point falls on the line:
    // t = 0 -> projection is at the start point (lx1, ly1)
    // t = 1 -> projection is at the end point (lx2, ly2)
    // 0 < t < 1 -> projection is within the segment
    // t < 0 or t > 1 -> projection is outside the segment
    const t = ((px - lx1) * lx + (py - ly1) * ly) / lineLengthSq;

    let closestX, closestY;

    if (t < 0) {
        closestX = lx1;
        closestY = ly1;
    } else if (t > 1) {
        closestX = lx2;
        closestY = ly2;
    } else {
        closestX = lx1 + t * lx;
        closestY = ly1 + t * ly;
    }

    // Calculate the distance between the given point (px, py) and the closest point
    var dx = px - closestX;
    var dy = py - closestY;
    return Math.sqrt(dx * dx + dy * dy);
}



