// For the #WCCChallenge, theme: "things fall apart."

const dsize = 8;
let dots = [];
let together = false;
let peel = 0;
let fc = 0; //framecount

function setup() {
	createCanvas(windowHeight, windowHeight);
	angleMode(DEGREES);
	makeSymbol();
	setTimeout(swap, 1000);
	setInterval(swap, 5000);
	colorMode(HSB, 360, 360, 360);
}

function makeSymbol() {
	let count = 0;
	for (let r = 300; r > 0; r -= dsize) {
		let ring = TAU * r;
		let num = floor(ring / dsize);
		for (let a = 0; a < 360; a += (Math.max(0.001, Math.abs(360 / num)) || 1)) {
			let x = cos(a) * r;
			let y = sin(a) * r;
			let add = (r >= 240) || (dtoS(0, 300, 0, -300, x, y) <= 30) || (dtoS(0, 0, cos(150) * 300, sin(150) * 300, x, y) <= 30) || (dtoS(0, 0, cos(30) * 300, sin(30) * 300, x, y) <= 30);
			if (!add) continue;
			let d = new Dot(createVector(x, y), a + 180, count);
			count++;
			dots.push(d);
		}
	}
}

function draw() {
	background('#000000aa');
	translate(width / 2, height / 2);
	scale(height / 700);
	for (let d of dots) {
		d.show();
	}
	fc++;
}

function swap() {
	together = !together;
	for (let d of dots) {
		if (together) d.tpos = d.opos;
		else d.tpos = p5.Vector.random2D().mult(random(-300, 300));
	}
	peel = (peel + 1) % 5;
	frameCount = 0;
}

class Dot {
	constructor(pos, ang, id) {
		this.pos = p5.Vector.random2D().mult(random(-300, 300));
		this.opos = createVector(pos.x, pos.y);
		this.tpos = createVector(this.pos.x, this.pos.y);
		this.h = ang % 360;
		this.id = [map(pos.y, 300, -300, 0, 1000), map(id, 0, 2500, 0, 1000), map(pos.x, -300, 300, 0, 1000), map((ang+270) % 360, 0, 360, 0, 1000), floor(random(1000))];
	}
	show() {
		if (10 * frameCount > this.id[peel] + random(20)) this.pos.lerp(this.tpos, 0.1)
		push();
		translate(this.pos);
		stroke(this.h, 360, 360, (cos(fc*2)/4+0.5));
		strokeWeight(dsize / 10 * (sin(fc*2)+3.0));
		point(0, 0);
		pop();
	}
}
